branches = {"master": "a1b2c3d"}
current = "master"
commits = {"a1b2c3d": "Add app.js entry point and .gitignore"}

def create_branch(name):
    branches[name] = branches[current]

def switch(name):
    global current
    current = name

def commit(sha, message):
    commits[sha] = message
    branches[current] = sha

def list_branches():
    for name in sorted(branches):
        marker = "*" if name == current else " "
        print(f"{marker} {name}")

create_branch("feature/auth")
list_branches()
switch("feature/auth")
commit("5b3c2d1", "Add login function")
print(f"[{current} {branches[current]}] {commits[branches[current]]}")
list_branches()
